var _markdown = "\n\n`sa` · 扩展 `default` · SCM 原生命令\n\n共 20 条。写法见 [Lua](/docs/cleo/syntax) / [Redux](/docs/cleo/syntax-redux)。\n\n## 开车路 [#开车路]\n\n<Opcode id=\"01E7\" name=\"SWITCH_ROADS_ON\" member=\"Path.SwitchRoadsOn\">\n  开启盒内车道路径。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      01E7 SWITCH_ROADS_ON\n      in: leftBottomX, leftBottomY, leftBottomZ, rightTopX, rightTopY, rightTopZ\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      switchRoadsOn(leftBottomX, leftBottomY, leftBottomZ, rightTopX, rightTopY, rightTopZ)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      Path.switchRoadsOn(leftBottomX, leftBottomY, leftBottomZ, rightTopX, rightTopY, rightTopZ)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 关车路 [#关车路]\n\n<Opcode id=\"01E8\" name=\"SWITCH_ROADS_OFF\" member=\"Path.SwitchRoadsOff\">\n  关闭盒内车道路径。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      01E8 SWITCH_ROADS_OFF\n      in: leftBottomX, leftBottomY, leftBottomZ, rightTopX, rightTopY, rightTopZ\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      switchRoadsOff(leftBottomX, leftBottomY, leftBottomZ, rightTopX, rightTopY, rightTopZ)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      Path.switchRoadsOff(leftBottomX, leftBottomY, leftBottomZ, rightTopX, rightTopY, rightTopZ)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 开人路 [#开人路]\n\n<Opcode id=\"022A\" name=\"SWITCH_PED_ROADS_ON\" member=\"Path.SwitchPedRoadsOn\">\n  开启盒内行人路径。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      022A SWITCH_PED_ROADS_ON\n      in: leftBottomX, leftBottomY, leftBottomZ, rightTopX, rightTopY, rightTopZ\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      switchPedRoadsOn(leftBottomX, leftBottomY, leftBottomZ, rightTopX, rightTopY, rightTopZ)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      Path.switchPedRoadsOn(leftBottomX, leftBottomY, leftBottomZ, rightTopX, rightTopY, rightTopZ)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 关人路 [#关人路]\n\n<Opcode id=\"022B\" name=\"SWITCH_PED_ROADS_OFF\" member=\"Path.SwitchPedRoadsOff\">\n  关闭盒内行人路径。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      022B SWITCH_PED_ROADS_OFF\n      in: leftBottomX, leftBottomY, leftBottomZ, rightTopX, rightTopY, rightTopZ\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      switchPedRoadsOff(leftBottomX, leftBottomY, leftBottomZ, rightTopX, rightTopY, rightTopZ)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      Path.switchPedRoadsOff(leftBottomX, leftBottomY, leftBottomZ, rightTopX, rightTopY, rightTopZ)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 最近人节点 [#最近人节点]\n\n<Opcode id=\"02C0\" name=\"GET_CLOSEST_CHAR_NODE\" member=\"Path.GetClosestCharNode\">\n  最近可行人节点坐标。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      02C0 GET_CLOSEST_CHAR_NODE\n      in: x, y, z\n      out: nodeX, nodeY, nodeZ\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      local nodeX, nodeY, nodeZ = getClosestCharNode(x, y, z)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      const { nodeX, nodeY, nodeZ } = Path.getClosestCharNode(x, y, z)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 最近车节点 [#最近车节点]\n\n<Opcode id=\"02C1\" name=\"GET_CLOSEST_CAR_NODE\" member=\"Path.GetClosestCarNode\">\n  最近可驶车节点坐标。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      02C1 GET_CLOSEST_CAR_NODE\n      in: x, y, z\n      out: nodeX, nodeY, nodeZ\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      local nodeX, nodeY, nodeZ = getClosestCarNode(x, y, z)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      const { nodeX, nodeY, nodeZ } = Path.getClosestCarNode(x, y, z)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 车节点 + 朝向 [#车节点--朝向]\n\n<Opcode id=\"03D3\" name=\"GET_CLOSEST_CAR_NODE_WITH_HEADING\" member=\"Path.GetClosestCarNodeWithHeading\">\n  最近车节点 + 朝向。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      03D3 GET_CLOSEST_CAR_NODE_WITH_HEADING\n      in: x, y, z\n      out: nodeX, nodeY, nodeZ, angle\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      local nodeX, nodeY, nodeZ, angle = getClosestCarNodeWithHeading(x, y, z)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      const { nodeX, nodeY, nodeZ, angle } = Path.getClosestCarNodeWithHeading(x, y, z)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 最近直线路 [#最近直线路]\n\n<Opcode id=\"04B9\" name=\"GET_CLOSEST_STRAIGHT_ROAD\" member=\"Path.GetClosestStraightRoad\">\n  距离范围内最近直线路段两端点与朝向。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      04B9 GET_CLOSEST_STRAIGHT_ROAD\n      in: x, y, z, minDist, maxDist\n      out: node1X, node1Y, node1Z, node2X, node2Y, node2Z, angle\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      local node1X, node1Y, node1Z, node2X, node2Y, node2Z, angle = getClosestStraightRoad(x, y, z, minDist, maxDist)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      const { node1X, node1Y, node1Z, node2X, node2Y, node2Z, angle } = Path.getClosestStraightRoad(x, y, z, minDist, maxDist)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 第 n 车节点 [#第-n-车节点]\n\n<Opcode id=\"04D3\" name=\"GET_NTH_CLOSEST_CAR_NODE\" member=\"Path.GetNthClosestCarNode\">\n  第 n 近的车节点。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      04D3 GET_NTH_CLOSEST_CAR_NODE\n      in: fromX, fromY, fromZ, n\n      out: x, y, z\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      local x, y, z = getNthClosestCarNode(fromX, fromY, fromZ, n)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      const { x, y, z } = Path.getNthClosestCarNode(fromX, fromY, fromZ, n)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 清空任务路线 [#清空任务路线]\n\n<Opcode id=\"05D6\" name=\"FLUSH_ROUTE\" member=\"Path.FlushRoute\">\n  清空任务路线点。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      05D6 FLUSH_ROUTE\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      flushRoute()\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      Path.flushRoute()\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 加任务路线点 [#加任务路线点]\n\n<Opcode id=\"05D7\" name=\"EXTEND_ROUTE\" member=\"Path.ExtendRoute\">\n  给任务路线加点。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      05D7 EXTEND_ROUTE\n      in: x, y, z\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      extendRoute(x, y, z)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      Path.extendRoute(x, y, z)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 加载区节点 [#加载区节点]\n\n<Opcode id=\"0606\" name=\"LOAD_PATH_NODES_IN_AREA\" member=\"Path.LoadPathNodesInArea\">\n  加载区路径节点（脚本车可避此区一类用途）。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0606 LOAD_PATH_NODES_IN_AREA\n      in: leftBottomX, leftBottomY, rightTopX, rightTopY\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      loadPathNodesInArea(leftBottomX, leftBottomY, rightTopX, rightTopY)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      Path.loadPathNodesInArea(leftBottomX, leftBottomY, rightTopX, rightTopY)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 释放节点 [#释放节点]\n\n<Opcode id=\"0607\" name=\"RELEASE_PATH_NODES\" member=\"Path.ReleaseNodes\">\n  释放 `0606` 相关限制 / 节点。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0607 RELEASE_PATH_NODES\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      releasePathNodes()\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      Path.releaseNodes()\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 第 n 车节点 + 朝向 [#第-n-车节点--朝向]\n\n<Opcode id=\"06F8\" name=\"GET_NTH_CLOSEST_CAR_NODE_WITH_HEADING\" member=\"Path.GetNthClosestCarNodeWithHeading\">\n  第 n 近车节点 + 朝向。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      06F8 GET_NTH_CLOSEST_CAR_NODE_WITH_HEADING\n      in: xCoord, yCoord, zCoord, nth\n      out: x, y, z, heading\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      local x, y, z, heading = getNthClosestCarNodeWithHeading(xCoord, yCoord, zCoord, nth)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      const { x, y, z, heading } = Path.getNthClosestCarNodeWithHeading(xCoord, yCoord, zCoord, nth)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 清空巡逻 [#清空巡逻]\n\n<Opcode id=\"0754\" name=\"FLUSH_PATROL_ROUTE\" member=\"Path.FlushPatrolRoute\">\n  清空巡逻路线，准备 `0755` 重建。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0754 FLUSH_PATROL_ROUTE\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      flushPatrolRoute()\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      Path.flushPatrolRoute()\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 加巡逻点 [#加巡逻点]\n\n<Opcode id=\"0755\" name=\"EXTEND_PATROL_ROUTE\" member=\"Path.ExtendPatrolRoute\">\n  巡逻路线加点（可带动画）。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0755 EXTEND_PATROL_ROUTE\n      in: x, y, z, animationName, animationFile\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      extendPatrolRoute(x, y, z, animationName, animationFile)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      Path.extendPatrolRoute(x, y, z, animationName, animationFile)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 车路恢复 [#车路恢复]\n\n<Opcode id=\"091D\" name=\"SWITCH_ROADS_BACK_TO_ORIGINAL\" member=\"Path.SwitchRoadsBackToOriginal\">\n  盒内车路恢复 `01E7` / `01E8` 改动前。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      091D SWITCH_ROADS_BACK_TO_ORIGINAL\n      in: leftBottomX, leftBottomY, leftBottomZ, rightTopX, rightTopY, rightTopZ\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      switchRoadsBackToOriginal(leftBottomX, leftBottomY, leftBottomZ, rightTopX, rightTopY, rightTopZ)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      Path.switchRoadsBackToOriginal(leftBottomX, leftBottomY, leftBottomZ, rightTopX, rightTopY, rightTopZ)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 人路恢复 [#人路恢复]\n\n<Opcode id=\"091E\" name=\"SWITCH_PED_ROADS_BACK_TO_ORIGINAL\" member=\"Path.SwitchPedRoadsBackToOriginal\">\n  盒内人路恢复 `022A` / `022B` 改动前。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      091E SWITCH_PED_ROADS_BACK_TO_ORIGINAL\n      in: leftBottomX, leftBottomY, leftBottomZ, rightTopX, rightTopY, rightTopZ\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      switchPedRoadsBackToOriginal(leftBottomX, leftBottomY, leftBottomZ, rightTopX, rightTopY, rightTopZ)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      Path.switchPedRoadsBackToOriginal(leftBottomX, leftBottomY, leftBottomZ, rightTopX, rightTopY, rightTopZ)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 禁止闲逛节点 [#禁止闲逛节点]\n\n<Opcode id=\"0994\" name=\"MARK_ROAD_NODE_AS_DONT_WANDER\" member=\"Path.MarkRoadNodeAsDontWander\">\n  标记节点禁止闲逛路过。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0994 MARK_ROAD_NODE_AS_DONT_WANDER\n      in: x, y, z\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      markRoadNodeAsDontWander(x, y, z)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      Path.markRoadNodeAsDontWander(x, y, z)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 清禁止闲逛 [#清禁止闲逛]\n\n<Opcode id=\"0995\" name=\"UNMARK_ALL_ROAD_NODES_AS_DONT_WANDER\" member=\"Path.UnmarkAllRoadNodesAsDontWander\">\n  清除全部「禁止闲逛」节点标记。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0995 UNMARK_ALL_ROAD_NODES_AS_DONT_WANDER\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      unmarkAllRoadNodesAsDontWander()\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      Path.unmarkAllRoadNodesAsDontWander()\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n";
